def sc(id,line,visual=None,choices=None,**kw):
 S[id]={'line':line,'mood':'thinking','choices':choices or [],**kw}
 if visual:S[id]['visual']=visual

def count(a,b,cap,cafe=False):
 return {'type':'counters','items':[{'label':'Your profit (₹)' if cafe else 'Your prison years','value':a},{'label':'Other café profit (₹)' if cafe else 'Ravi’s prison years','value':b}],'caption':cap}
rule='Deal · You/Ravi: silent/silent 1/1; confess/silent 0/5; silent/confess 5/0; confess/confess 3/3 years.'
