sc('ravi_only','Only Ravi changes from confession to silence. His three years become five. Your three become zero.',count(0,5,'WHAT-IF · BEFORE both confess 3/3 → only Ravi silent 0/5. '+rule),[ch('From 3/3: silence both','joint_second')],consequence=True)
